using System.IO;
using Autodesk.Revit.DB;

var doc = Document;
// export into the connector's exports workspace so the file can be fetched by the caller
var dir = Connector.ExportsDirectory;
var name = "model";
var opts = new IFCExportOptions();

// IFC export writes temporary data into the document, so it needs an open transaction
// (unlike DWG export, which manages its own and must be called with none open).
bool ok = false;
Connector.WithTransaction(doc, () => {
    ok = doc.Export(dir, name, opts);
});

// publish the written .ifc so it comes back to the caller (same pattern as the DWG how-to)
var file = Path.Combine(dir, name + ".ifc");
Connector.Publish(file);

return new { ok, published = Path.GetFileName(file), exists = File.Exists(file), sizeBytes = File.Exists(file) ? new FileInfo(file).Length : 0L };
